CREATE TABLE products (
    product_id  integer PRIMARY KEY,
    name        text          NOT NULL,
    price       numeric(10,2) NOT NULL,
    stock       integer       NOT NULL CHECK (stock >= 0)
);

INSERT INTO products (product_id, name, price, stock) VALUES
    (1, 'USB-C cable',          299.00, 40),
    (2, 'Wireless mouse',       799.00, 15),
    (3, 'Laptop stand',        1499.00,  3),
    (4, 'Mechanical keyboard', 3499.00,  0);

SELECT * FROM products ORDER BY product_id;

BEGIN;
UPDATE products
   SET price = round(price * 1.10, 2)
 WHERE price < 1000
RETURNING product_id, price;
ROLLBACK;

BEGIN;
UPDATE products AS p
   SET price = round(p.price * 1.10, 2)
  FROM (SELECT product_id, price
          FROM products
         WHERE price < 1000
           FOR UPDATE) AS before
 WHERE p.product_id = before.product_id
RETURNING p.product_id, before.price AS old_price, p.price AS new_price;
ROLLBACK;

-- Session A
BEGIN;
UPDATE products SET stock = stock - 5 WHERE product_id = 1
RETURNING old.stock AS stock_before, new.stock AS stock_after;
-- (do not commit yet)

-- Session B, while A is still open
UPDATE products SET stock = stock - 5 WHERE product_id = 1
RETURNING old.stock AS stock_before, new.stock AS stock_after;

-- Session A
COMMIT;

DELETE FROM products
 WHERE product_id = 6
RETURNING old.product_id, old.name, old.price, new.name AS new_name;

